// where the massif stands (ridges and gullies): its spine runs along X a little off the centre towards -Z
const s = (samples - 1) * spacing, r = Math.hypot(x / 1.35, z + 0.06 * s) / s;
return pow(1 - smoothstep(0.1, 0.5, r), 2);

// a peak with concave flanks under the ridges (0..1 here, metres further on)
const s = (samples - 1) * spacing, r = Math.hypot(x / 1.35, z + 0.06 * s) / s;
return 1.0 * pow(clamp(1 - r / 0.45, 0, 1), 1.6);

// gullies on the massif where the rain of 2 to 7 cells gathers
const cells = (Math.exp(drainage) - 1) / (cell * cell);
return smoothstep(2, 7, Math.log(1 + cells)) * smoothstep(0.1, 0.5, mask);

