// the road's centre line, winding across the map along X over the massif's +Z flank, a road's width from the edges
const s = (samples - 1) * spacing, w = Math.max(6, 3 * spacing), x = (t - 0.5) * (s - 2 * w);
const a = 2 + 2.39996 * seed, b = 0.5 + 3.88322 * seed; // the bends' phases, a golden angle further per seed
return [x, 0, s * (0.24 + 0.07 * sin(TAU * 0.9 * x / s + a) + 0.03 * sin(TAU * 2.1 * x / s + b))];

params.expression:
// forest on gentle grass, in patches that grow with tree_density
const t = 1.05 - 1.1 * tree_density;
return gentle * grass * smoothstep(t - 0.05, t + 0.05, cover);

params.code:
// a random size and heading; oaks low down, conifers higher up, none above the tree line
@pscale = fit(rand(@ptnum, seed, 7), 0, 1, 0.75, 1.25);
f@yaw = 360 * rand(@ptnum, seed, 6);
const up = clamp(@height / height, 0, 1), oak = 0.5 - 0.45 * up, u = rand(@ptnum, seed, 5);
const v = u < oak ? 'oak' : u < oak + (1 - oak) * 0.5 ? 'pine' : 'fir';
s@variant = v;
// whole trees on the map and clear of the road (input 1, flat at y = 0): how far the corners of each tree's box
// reach from its trunk in X and Z, at scale 1
const r = { pine: 2.7, fir: 3.5, oak: 4.4 }[v] * @pscale, edge = (samples - 1) * spacing / 2 - r;
const onRoad = road && xyzdist(1, [@P.x, 0, @P.z]) < r;
if (Math.abs(@P.x) > edge || Math.abs(@P.z) > edge || onRoad || up > 0.78 + 0.15 * rand(@ptnum, seed, 4)) removepoint(0, @ptnum);

// how far each tree stands above (+) or below (-) the ground under it
const n = Math.round(Math.sqrt(npoints(1))), o = point(1, 'P', 0), cell = point(1, 'P', 1)[0] - o[0];
const fx = (@P.x - o[0]) / cell, fz = (@P.z - o[2]) / cell;
const i = clamp(Math.floor(fx), 0, n - 2), j = clamp(Math.floor(fz), 0, n - 2), u = fx - i, v = fz - j;
const h = (a, b) => point(1, 'P', (j + b) * n + i + a)[1];
const y = u >= v ? h(0, 0) + u * (h(1, 0) - h(0, 0)) + v * (h(1, 1) - h(1, 0)) : h(0, 0) + v * (h(0, 1) - h(0, 0)) + u * (h(1, 1) - h(0, 1));
f@ground_gap = @P.y - y;

// how far each instance keeps clear of the road (m): its distance from the centre line in X and Z, less half the
// road's width and the reach of its box (the source's own box, turned, tilted and scaled as placed)
const b = primintrinsic(0, 'packedbounds', @primnum), m = primintrinsic(0, 'transform', @primnum).flat();
let reach = 0;
for (const x of [b[0], b[1]]) for (const y of [b[2], b[3]]) for (const z of [b[4], b[5]])
  reach = Math.max(reach, Math.hypot(x * m[0] + y * m[3] + z * m[6], x * m[2] + y * m[5] + z * m[8]));
const p = point(0, 'P', primpoints(0, @primnum)[0]);
f@road_gap = road ? xyzdist(1, [p[0], 0, p[2]]) - reach : 1e9; // no road: nothing to keep clear of

// three shapes, a random size and heading
@pscale = fit(rand(@ptnum, seed, 11), 0, 1, 0.7, 1.6);
f@yaw = 360 * rand(@ptnum, seed, 10);
const v = pick(['boulder', 'slab', 'stone'], rand(@ptnum, seed, 9));
s@variant = v;
// whole rocks on the map and clear of the road (input 1, flat at y = 0): how far the corners of each rock's box reach
// from its centre, tilted any way, at scale 1
const r = { boulder: 2.75, slab: 2.7, stone: 1.85 }[v] * @pscale, edge = (samples - 1) * spacing / 2 - r;
const onRoad = road && xyzdist(1, [@P.x, 0, @P.z]) < r;
if (Math.abs(@P.x) > edge || Math.abs(@P.z) > edge || onRoad) removepoint(0, @ptnum);

// how far each rock stands above (+) or below (-) the ground under it
const n = Math.round(Math.sqrt(npoints(1))), o = point(1, 'P', 0), cell = point(1, 'P', 1)[0] - o[0];
const fx = (@P.x - o[0]) / cell, fz = (@P.z - o[2]) / cell;
const i = clamp(Math.floor(fx), 0, n - 2), j = clamp(Math.floor(fz), 0, n - 2), u = fx - i, v = fz - j;
const h = (a, b) => point(1, 'P', (j + b) * n + i + a)[1];
const y = u >= v ? h(0, 0) + u * (h(1, 0) - h(0, 0)) + v * (h(1, 1) - h(1, 0)) : h(0, 0) + v * (h(0, 1) - h(0, 0)) + u * (h(1, 1) - h(0, 1));
f@ground_gap = @P.y - y;

// how far each instance keeps clear of the road (m): its distance from the centre line in X and Z, less half the
// road's width and the reach of its box (the source's own box, turned, tilted and scaled as placed)
const b = primintrinsic(0, 'packedbounds', @primnum), m = primintrinsic(0, 'transform', @primnum).flat();
let reach = 0;
for (const x of [b[0], b[1]]) for (const y of [b[2], b[3]]) for (const z of [b[4], b[5]])
  reach = Math.max(reach, Math.hypot(x * m[0] + y * m[3] + z * m[6], x * m[2] + y * m[5] + z * m[8]));
const p = point(0, 'P', primpoints(0, @primnum)[0]);
f@road_gap = road ? xyzdist(1, [p[0], 0, p[2]]) - reach : 1e9; // no road: nothing to keep clear of

// every point of the road onto the ground under it, 5 cm up
const n = Math.round(Math.sqrt(npoints(1))), o = point(1, 'P', 0), cell = point(1, 'P', 1)[0] - o[0];
const fx = (@P.x - o[0]) / cell, fz = (@P.z - o[2]) / cell;
const i = clamp(Math.floor(fx), 0, n - 2), j = clamp(Math.floor(fz), 0, n - 2), u = fx - i, v = fz - j;
const h = (a, b) => point(1, 'P', (j + b) * n + i + a)[1];
const y = u >= v ? h(0, 0) + u * (h(1, 0) - h(0, 0)) + v * (h(1, 1) - h(1, 0)) : h(0, 0) + v * (h(0, 1) - h(0, 0)) + u * (h(1, 1) - h(0, 1));
@P.y = y + 0.05;

// the weight layers as colours: grass (paler up high), grey rock, a gravel road
const g = mix([0.27, 0.42, 0.16], [0.47, 0.53, 0.27], clamp(@P.y / height, 0, 1));
@Cd = add(add(mul(g, @grass), mul([0.5, 0.48, 0.45], @rock)), mul([0.42, 0.36, 0.28], @road));
